// Extrae keywords de ciclos para filtrar Qdrant
const q = $json.pregunta.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, ''); // quitar tildes

const cycleMap = [
  { keywords: ['dam', 'multiplataforma'],        filter: 'DAM' },
  { keywords: ['daw', 'aplicaciones web'],        filter: 'DAW' },
  { keywords: ['smr', 'microinformatica', 'redes'], filter: 'SMR' },
  { keywords: ['asir', 'administracion de sistemas', 'redes (asir)'], filter: 'ASIR' },
  { keywords: ['ia', 'inteligencia artificial'],  filter: 'Inteligencia Artificial' },
  { keywords: ['ciberseguridad'],                 filter: 'Ciberseguridad' },
  { keywords: ['enfermeria', 'cae'],              filter: 'Enfermería' },
  { keywords: ['laboratorio', 'lcb'],             filter: 'Laboratorio' },
  { keywords: ['optica', 'op '],                  filter: 'Óptica' },
  { keywords: ['protesis', 'pt '],                filter: 'Prótesis' },
  { keywords: ['gat', 'alojamientos', 'turisticos'], filter: 'GAT' },
  { keywords: ['giat', 'guia', 'asistencias'],    filter: 'GIAT' },
  { keywords: ['avge', 'agencias de viajes', 'eventos'], filter: 'AVGE' },
  { keywords: ['logistica'],                      filter: 'Logística' },
  { keywords: ['marketing', 'publicidad'],        filter: 'Marketing' },
  { keywords: ['comercio internacional'],         filter: 'Comercio' },
  { keywords: ['ade', 'administracion', 'finanzas'], filter: 'Administración' },
  { keywords: ['secretariado', 'asistencia'],     filter: 'Asistencia' },
];

let keyword = null;
for (const entry of cycleMap) {
  if (entry.keywords.some(k => q.includes(k))) {
    keyword = entry.filter;
    break;
  }
}

return [{ json: {
  pregunta: $json.pregunta,
  sessionId: $json.sessionId,
  keyword  // null si no hay ciclo específico
} }];

// Construir query Qdrant con o sin filtro keyword
const embedding = items[0].json.embedding;
const keyword  = $('Extract Keyword').first().json.keyword;
const pregunta = $('Extract Keyword').first().json.pregunta;
const sessionId = $('Extract Keyword').first().json.sessionId;

const body = {
  vector: embedding,
  limit: 6,
  with_payload: true
};

if (keyword) {
  body.filter = {
    must: [{ key: 'content', match: { text: keyword } }]
  };
}

return [{ json: { qdrantBody: body, pregunta, sessionId, keyword } }];

const results  = items[0].json.result || [];
const pregunta = $('Build Qdrant Query').first().json.pregunta;
const sessionId = $('Build Qdrant Query').first().json.sessionId;
const keyword  = $('Build Qdrant Query').first().json.keyword;

let context;
if (results.length === 0) {
  context = 'No se encontró información específica en la base de conocimiento.';
} else {
  context = results
    .map(r => (r.payload?.content || '').trim())
    .filter(Boolean)
    .join('\n\n---\n\n');
}

const prompt = `CONTEXTO DE LA BASE DE CONOCIMIENTO DEL CENTRO DE FP EJEMPLO${keyword ? ' (filtrado: ' + keyword + ')' : ''}:\n\n${context}\n\n---\n\nPREGUNTA: ${pregunta}`;

return [{ json: { prompt, pregunta, sessionId } }];
